package com.example.personalagent.service;

import com.example.personalagent.AgentConfig;
import com.example.personalagent.storage.Store;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.*;
import java.util.*;
import static com.example.personalagent.Api.*;

@Service
public class VaultService {
    private final AgentConfig config;private final Store store;private final ObjectMapper json;
    private final String[] folders={"00-导航","10-我的资料/变更记录","20-阅读与知识/书籍","20-阅读与知识/阅读笔记","20-阅读与知识/原始笔记","30-生活与见解/记录","30-生活与见解/人工心得","40-想法与行动/想法","40-想法与行动/行动","40-想法与行动/进展","40-想法与行动/结果","50-财富/快照","50-财富/复盘","60-对话与复盘/对话","60-对话与复盘/综合复盘","90-模板","99-附件"};
    public VaultService(AgentConfig config,Store store,ObjectMapper json)throws Exception{this.config=config;this.store=store;this.json=json;for(String folder:folders)Files.createDirectories(config.vaultPath().resolve(folder));initialize();}
    private void initialize()throws Exception{
        createOnce("00-导航/首页.md","# 个人 Agent\n\n[[10-我的资料/当前档案|当前档案]] · [[10-我的资料/当前目标|当前目标]] · [[50-财富/当前概览|财富概览]]\n\n![[历史时间线.base]]\n\n目录按主题组织，历史文件按**记录时间**存放；表格按**事件时间**倒序查看。未知事件时间采用记录时间，页面明确标注。每条记录使用稳定 UUID，标题相同也不会混淆。\n\n网页维护系统记录；请在 `30-生活与见解/人工心得` 或 `20-阅读与知识/原始笔记` 写手工笔记，点击网页“重建索引”即可供 Agent 检索。直接编辑系统记录会进入待核对状态，不会静默覆盖。\n\n没有 Bases 时，可使用文件搜索和下方目录查看 Markdown。\n");
        createOnce("90-模板/生活见解.md","---\ntype: manual\noccurred_at: \ntags: [个人见解]\n---\n\n# 标题\n\n## 发生了什么\n\n## 我的理解\n\n## 待验证\n");
        base("历史时间线","note.type != \"manual\"");base("想法与行动","note.type == \"idea\" || note.type == \"action\" || note.type == \"progress\" || note.type == \"result\"");base("阅读与见解","note.type == \"book\" || note.type == \"reading\" || note.type == \"insight\" || note.type == \"life\"");base("财富记录","note.type == \"finance_snapshot\" || note.type == \"finance_review\"");base("待核对","note.review_required == true");
    }
    private void base(String title,String filter)throws Exception{createOnce("00-导航/"+title+".base","filters:\n  and:\n    - 'file.ext == \"md\"'\n    - 'note.id != null'\n    - '"+filter+"'\nviews:\n  - type: table\n    name: "+title+"\n    order:\n      - file.name\n      - note.type\n      - note.status\n      - note.event_at\n      - note.recorded_at\n      - note.id\n    sort:\n      - property: note.event_at\n        direction: DESC\n      - property: note.recorded_at\n        direction: DESC\n      - property: note.id\n        direction: DESC\n");}
    private void createOnce(String name,String content)throws Exception{Path path=safe(name);if(!Files.exists(path))atomic(path,content);}
    public Path safe(String relative)throws Exception{Path root=config.vaultPath().toRealPath(),path=root.resolve(relative).normalize();if(!path.startsWith(root))throw new IllegalArgumentException("路径越界");Path current=path.getParent();while(current!=null&&!current.equals(root)){if(Files.exists(current)&&(!current.toRealPath().startsWith(root)||Files.isSymbolicLink(current)))throw new IllegalArgumentException("不允许链接目录");current=current.getParent();}if(Files.isSymbolicLink(path))throw new IllegalArgumentException("不允许链接文件");return path;}
    public static String hash(byte[] data){try{byte[] digest=MessageDigest.getInstance("SHA-256").digest(data);StringBuilder b=new StringBuilder();for(byte d:digest)b.append(String.format("%02x",d));return b.toString();}catch(Exception e){throw new IllegalStateException(e);}}
    private void atomic(Path path,String content)throws Exception{Files.createDirectories(path.getParent());Path temp=Files.createTempFile(path.getParent(),".agent-",".tmp");try{Files.write(temp,content.getBytes(StandardCharsets.UTF_8));try{Files.move(temp,path,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(temp,path,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(temp);}}
    private String directory(Map<String,Object> r){String kind=text(r,"kind"),folder;switch(kind){case "idea":folder="40-想法与行动/想法";break;case "action":folder="40-想法与行动/行动";break;case "progress":folder="40-想法与行动/进展";break;case "result":folder="40-想法与行动/结果";break;case "book":folder="20-阅读与知识/书籍";break;case "reading":folder="20-阅读与知识/阅读笔记";break;case "change":folder="10-我的资料/变更记录";break;case "finance_snapshot":folder="50-财富/快照";break;case "finance_review":folder="50-财富/复盘";break;case "conversation":case "message":folder="60-对话与复盘/对话";break;case "review":folder="60-对话与复盘/综合复盘";break;default:folder="30-生活与见解/记录";}
        if(!Arrays.asList("idea","action","book").contains(kind)){ZonedDateTime date=Instant.parse(text(r,"recorded_at")).atZone(ZoneId.of("Asia/Shanghai"));folder+="/"+date.getYear()+"/"+String.format("%02d",date.getMonthValue());}return folder;
    }
    public synchronized void flush(){
        for(Map<String,Object> p:store.list("publish")){String id=text(p,"record_id");Map<String,Object> r=store.get("records",id);if(r==null){if(!text(p,"path").isEmpty())try{Files.deleteIfExists(safe(text(p,"path")));}catch(Exception ignored){}store.remove("publish",id);continue;}if(!"pending".equals(p.get("state")))continue;publish(r,p);}
        current("10-我的资料/当前档案.md",profile());
        StringBuilder goals=new StringBuilder("# 当前目标\n\n");for(Map<String,Object> r:store.list("records"))if(("idea".equals(r.get("kind"))&&"validating".equals(r.get("status")))||("action".equals(r.get("kind"))&&"open".equals(r.get("status"))))goals.append(link(r)).append(" · ").append(text(r,"status")).append("\n\n");current("10-我的资料/当前目标.md",goals.toString());
        StringBuilder history=new StringBuilder("# 历史时间线（Markdown 备用）\n\n");store.list("records").stream().sorted(Comparator.comparing((Map<String,Object> r)->text(r,"event_at")).reversed()).limit(500).forEach(r->history.append(text(r,"event_at")).append(" · ").append(link(r)).append(" · ").append(text(r,"status")).append("\n\n"));current("00-导航/最近历史.md",history.toString());
    }
    private String link(Map<String,Object> r){String path=directory(r)+"/"+text(r,"id");return "[["+path+"|"+text(r,"title").replace("|"," ").replace("]"," ")+"]]";}
    private String profile(){StringBuilder s=new StringBuilder("# 当前档案\n\n仅包含你明确提供且仍有效的记忆。\n\n");Map<String,Map<String,Object>> facts=new HashMap<>();for(Map<String,Object> m:store.list("memories"))if("active".equals(m.get("status"))){String key=text(m,"fact_key");Map<String,Object> old=facts.get(key);if(old==null||text(m,"valid_from").compareTo(text(old,"valid_from"))>0||(text(m,"valid_from").equals(text(old,"valid_from"))&&Boolean.TRUE.equals(m.get("user_corrected"))))facts.put(key,m);}for(Map<String,Object> m:facts.values()){s.append("- ").append(text(m,"content")).append("（").append(text(m,"kind")).append("）\n  来源：");Map<String,Object> source=store.get("records",text(m,"source_id"));s.append(source==null?"手工笔记 "+text(m,"source_id"):link(source)).append("\n\n");}return s.toString();}
    private void publish(Map<String,Object> r,Map<String,Object> p){String relative=text(p,"path");if(relative.isEmpty())relative=directory(r)+"/"+text(r,"id")+".md";
        try{Path path=safe(relative);if(Files.exists(path)&&!hash(Files.readAllBytes(path)).equals(text(p,"content_hash"))){p.put("state","conflict");p.put("error","Obsidian 文件已有手工修改，请保留副本或在网页核对");p.put("path",relative);store.put("publish",text(r,"id"),p);return;}
            StringBuilder body=new StringBuilder("---\n");for(String key:Arrays.asList("id","status","event_at","recorded_at","updated_at","event_time_basis","revision","archived","important","entity_id","erroneous"))body.append(key).append(": ").append(json.writeValueAsString(r.get(key))).append("\n");body.append("type: ").append(json.writeValueAsString(r.get("kind"))).append("\nreview_required: false\n---\n\n# ").append(text(r,"title")).append("\n\n").append(text(r,"content")).append("\n\n");Map<String,Object> payload=(Map<String,Object>)r.get("payload");for(Map.Entry<String,Object> entry:payload.entrySet())body.append("## ").append(entry.getKey()).append("\n\n").append(entry.getValue() instanceof String?entry.getValue():json.writerWithDefaultPrettyPrinter().writeValueAsString(entry.getValue())).append("\n\n");if(r.get("entity_id")!=null){Map<String,Object> entity=store.get("records",text(r,"entity_id"));if(entity!=null)body.append("所属：").append(link(entity)).append("\n");}
            String content=body.toString();atomic(path,content);p.put("path",relative);p.put("content_hash",hash(content.getBytes(StandardCharsets.UTF_8)));p.put("state","published");p.put("error",null);p.put("updated_at",now());store.put("publish",text(r,"id"),p);
        }catch(Exception e){p.put("state","pending");p.put("error","文件发布失败，请检查目录权限");store.put("publish",text(r,"id"),p);}
    }
    public synchronized void current(String name,String content){String id="current:"+name;Map<String,Object> p=store.get("current_publish",id);try{Path file=safe(name);if(Files.exists(file)&&(p==null||!hash(Files.readAllBytes(file)).equals(text(p,"hash")))){store.put("current_publish",id,map("state","conflict","path",name,"hash",p==null?null:p.get("hash")));return;}String hash=hash(content.getBytes(StandardCharsets.UTF_8));if(p!=null&&hash.equals(p.get("hash")))return;atomic(file,content);store.put("current_publish",id,map("state","published","path",name,"hash",hash));}catch(Exception e){store.put("current_publish",id,map("state","pending","path",name));}}
    public synchronized Map<String,Object> resolve(String id,boolean keepManual)throws Exception{Map<String,Object> p=store.get("publish",id);require(p!=null&&"conflict".equals(p.get("state")),"没有待核对文件");Path file=safe(text(p,"path"));if(keepManual&&Files.exists(file)){String body=new String(Files.readAllBytes(file),StandardCharsets.UTF_8);atomic(safe("30-生活与见解/人工心得/保留-"+id+"-"+System.currentTimeMillis()+".md"),body);}p.put("content_hash",Files.exists(file)?hash(Files.readAllBytes(file)):null);p.put("state","pending");store.put("publish",id,p);flush();return store.get("publish",id);}
}
